    function new(string name = "direct_regmap_eeprom_eeprom_1");
        super.new(name, 32, build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));
        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.ecc_1 = uvm_reg_field::type_id::create("ecc_1");
        this.ptest = uvm_reg_field::type_id::create("ptest");
        this.factory_lot = uvm_reg_field::type_id::create("factory_lot");
        this.factory_wafer = uvm_reg_field::type_id::create("factory_wafer");
        this.ecc_1.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.ptest.configure(this, 4,  22, "RW", 0, 'd0, 1, 1, 0);
        this.factory_lot.configure(this, 16,  6, "RW", 0, 'd0, 1, 1, 0);
        this.factory_wafer.configure(this, 6,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
endclass
