    virtual function void build();
        this.ecc_7 = uvm_reg_field::type_id::create("ecc_7");
        this.mfs_h1_dis = uvm_reg_field::type_id::create("mfs_h1_dis");
        this.mfs_h2_dis = uvm_reg_field::type_id::create("mfs_h2_dis");
        this.mfs_scale_l = uvm_reg_field::type_id::create("mfs_scale_l");
        this.mfs_scale_h = uvm_reg_field::type_id::create("mfs_scale_h");
        this.ecc_7.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_h1_dis.configure(this, 1,  25, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_h2_dis.configure(this, 1,  24, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_scale_l.configure(this, 12,  12, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_scale_h.configure(this, 12,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
