        this.ecc_8 = uvm_reg_field::type_id::create("ecc_8");
        this.unused_8 = uvm_reg_field::type_id::create("unused_8");
        this.temp_offset = uvm_reg_field::type_id::create("temp_offset");
        this.mfs_offset = uvm_reg_field::type_id::create("mfs_offset");
        this.ecc_8.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.unused_8.configure(this, 2,  24, "RW", 0, 'd0, 1, 1, 0);
        this.temp_offset.configure(this, 12,  12, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_offset.configure(this, 12,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
