            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.ecc_a = uvm_reg_field::type_id::create("ecc_a");
        this.d_cvh_st_off = uvm_reg_field::type_id::create("d_cvh_st_off");
        this.cvh_st_erb = uvm_reg_field::type_id::create("cvh_st_erb");
        this.cvh_st_cmode = uvm_reg_field::type_id::create("cvh_st_cmode");
        this.unused_a = uvm_reg_field::type_id::create("unused_a");
        this.h2a_room = uvm_reg_field::type_id::create("h2a_room");
        this.angle_offset = uvm_reg_field::type_id::create("angle_offset");
        this.ecc_a.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.d_cvh_st_off.configure(this, 2,  24, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_st_erb.configure(this, 2,  22, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_st_cmode.configure(this, 2,  20, "RW", 0, 'd0, 1, 1, 0);
        this.unused_a.configure(this, 2,  18, "RW", 0, 'd0, 1, 1, 0);
        this.h2a_room.configure(this, 6,  12, "RW", 0, 'd0, 1, 1, 0);
        this.angle_offset.configure(this, 12,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
