    virtual function void build();
        this.ecc_15 = uvm_reg_field::type_id::create("ecc_15");
        this.lin_coeff_9 = uvm_reg_field::type_id::create("lin_coeff_9");
        this.lin_coeff_8 = uvm_reg_field::type_id::create("lin_coeff_8");
        this.ecc_15.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_9.configure(this, 13,  13, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_8.configure(this, 13,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
endclass
`endif



