        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.ecc_17 = uvm_reg_field::type_id::create("ecc_17");
        this.lin_coeff_13 = uvm_reg_field::type_id::create("lin_coeff_13");
        this.lin_coeff_12 = uvm_reg_field::type_id::create("lin_coeff_12");
        this.ecc_17.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_13.configure(this, 13,  13, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_12.configure(this, 13,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
endclass
