    virtual function void build();
        this.ecc_1d = uvm_reg_field::type_id::create("ecc_1d");
        this.unused_1d_a = uvm_reg_field::type_id::create("unused_1d_a");
        this.hyst_0_360 = uvm_reg_field::type_id::create("hyst_0_360");
        this.angle_hyst = uvm_reg_field::type_id::create("angle_hyst");
        this.pwm_freq = uvm_reg_field::type_id::create("pwm_freq");
        this.angle_ave = uvm_reg_field::type_id::create("angle_ave");
        this.miss_mag_thrsh = uvm_reg_field::type_id::create("miss_mag_thrsh");
        this.unused_1d_b = uvm_reg_field::type_id::create("unused_1d_b");
        this.inter_dis = uvm_reg_field::type_id::create("inter_dis");
        this.ovlo_dis = uvm_reg_field::type_id::create("ovlo_dis");
        this.ee_dbe_dis = uvm_reg_field::type_id::create("ee_dbe_dis");
        this.max_input_dis = uvm_reg_field::type_id::create("max_input_dis");
        this.min_input_dis = uvm_reg_field::type_id::create("min_input_dis");
        this.miss_mag_dis = uvm_reg_field::type_id::create("miss_mag_dis");
        this.ecc_1d.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.unused_1d_a.configure(this, 1,  25, "RW", 0, 'd0, 1, 1, 0);
        this.hyst_0_360.configure(this, 1,  24, "RW", 0, 'd0, 1, 1, 0);
        this.angle_hyst.configure(this, 2,  22, "RW", 0, 'd0, 1, 1, 0);
        this.pwm_freq.configure(this, 3,  19, "RW", 0, 'd0, 1, 1, 0);
        this.angle_ave.configure(this, 3,  16, "RW", 0, 'd0, 1, 1, 0);
        this.miss_mag_thrsh.configure(this, 9,  7, "RW", 0, 'd0, 1, 1, 0);
        this.unused_1d_b.configure(this, 1,  6, "RW", 0, 'd0, 1, 1, 0);
        this.inter_dis.configure(this, 1,  5, "RW", 0, 'd0, 1, 1, 0);
        this.ovlo_dis.configure(this, 1,  4, "RW", 0, 'd0, 1, 1, 0);
        this.ee_dbe_dis.configure(this, 1,  3, "RW", 0, 'd0, 1, 1, 0);
        this.max_input_dis.configure(this, 1,  2, "RW", 0, 'd0, 1, 1, 0);
        this.min_input_dis.configure(this, 1,  1, "RW", 0, 'd0, 1, 1, 0);
        this.miss_mag_dis.configure(this, 1,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
