        this.ecc_1e = uvm_reg_field::type_id::create("ecc_1e");
        this.dev_lock = uvm_reg_field::type_id::create("dev_lock");
        this.comm_lock = uvm_reg_field::type_id::create("comm_lock");
        this.abist_e = uvm_reg_field::type_id::create("abist_e");
        this.lbist_e = uvm_reg_field::type_id::create("lbist_e");
