        this.angle_ref = uvm_reg_field::type_id::create("angle_ref");
        this.unused_1e = uvm_reg_field::type_id::create("unused_1e");
        this.d_abe_bw = uvm_reg_field::type_id::create("d_abe_bw");
        this.polarity = uvm_reg_field::type_id::create("polarity");
        this.lin_coeff_scalar = uvm_reg_field::type_id::create("lin_coeff_scalar");
        this.lin_coeff_active = uvm_reg_field::type_id::create("lin_coeff_active");
        this.lin_bin_hyst = uvm_reg_field::type_id::create("lin_bin_hyst");
        this.lin_mode = uvm_reg_field::type_id::create("lin_mode");
        this.lin_enable = uvm_reg_field::type_id::create("lin_enable");
        this.ecc_1e.configure(this, 6,  26, "RW", 0, 'd0, 1, 1, 0);
        this.dev_lock.configure(this, 1,  25, "RW", 0, 'd0, 1, 1, 0);
        this.comm_lock.configure(this, 1,  24, "RW", 0, 'd0, 1, 1, 0);
        this.abist_e.configure(this, 2,  22, "RW", 0, 'd0, 1, 1, 0);
        this.lbist_e.configure(this, 2,  20, "RW", 0, 'd0, 1, 1, 0);
        this.dac_range.configure(this, 1,  19, "RW", 0, 'd0, 1, 1, 0);
        this.angle_ref.configure(this, 1,  18, "RW", 0, 'd0, 1, 1, 0);
        this.unused_1e.configure(this, 1,  17, "RW", 0, 'd0, 1, 1, 0);
        this.d_abe_bw.configure(this, 1,  16, "RW", 0, 'd0, 1, 1, 0);
        this.polarity.configure(this, 1,  15, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_scalar.configure(this, 1,  14, "RW", 0, 'd0, 1, 1, 0);
        this.lin_coeff_active.configure(this, 4,  10, "RW", 0, 'd0, 1, 1, 0);
        this.lin_bin_hyst.configure(this, 7,  3, "RW", 0, 'd0, 1, 1, 0);
        this.lin_mode.configure(this, 2,  1, "RW", 0, 'd0, 1, 1, 0);
        this.lin_enable.configure(this, 1,  0, "RW", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
    endfunction
    
endclass
