class direct_regmap_shadow_shadow_4 extends uvm_reg;
    `uvm_object_utils(direct_regmap_shadow_shadow_4)
    
    
    /*Reserved bit
    */
    rand uvm_reg_field reserved;
    
    
    /*Oscillator trimming during POR data.
    
    
    */
    rand uvm_reg_field d_osc_trim;
    
    
    /*Bias current trimming during POR data.
    
    
    */
    rand uvm_reg_field d_ibias_trim;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
        field_25: coverpoint {m_current[25],m_data[25]} iff (!m_is_read && m_be[3])
        {
            illegal_bins b_x = {1,2};
        }
        field_4: coverpoint {m_current[4],m_data[4]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_5: coverpoint {m_current[5],m_data[5]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_6: coverpoint {m_current[6],m_data[6]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_7: coverpoint {m_current[7],m_data[7]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_3: coverpoint {m_current[3],m_data[3]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
    endgroup
    
    covergroup rd_cg_bits;
        
        field_25: coverpoint {m_current[25],m_data[25]} iff (m_is_read && m_be[3])
        {
            illegal_bins b_x = {1,2};
        }
        field_4: coverpoint {m_current[4],m_data[4]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_5: coverpoint {m_current[5],m_data[5]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_6: coverpoint {m_current[6],m_data[6]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_7: coverpoint {m_current[7],m_data[7]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_3: coverpoint {m_current[3],m_data[3]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        
    endgroup
    
    covergroup wr_cg_vals;
        
        reserved : coverpoint reserved.value[0:0];
        
        d_osc_trim : coverpoint d_osc_trim.value[3:0];
        
        d_ibias_trim : coverpoint d_ibias_trim.value[3:0];
        
    endgroup
    
    covergroup rd_cg_vals;
        
        reserved : coverpoint reserved.value[0:0];
        
        d_osc_trim : coverpoint d_osc_trim.value[3:0];
        
        d_ibias_trim : coverpoint d_ibias_trim.value[3:0];
        
    endgroup
    
    // Function : new
    
    function new(string name = "direct_regmap_shadow_shadow_4");
        super.new(name, 32, build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));
        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.reserved = uvm_reg_field::type_id::create("reserved");
        this.d_osc_trim = uvm_reg_field::type_id::create("d_osc_trim");
        this.d_ibias_trim = uvm_reg_field::type_id::create("d_ibias_trim");
        this.reserved.configure(this, 1,  25, "RW", 0, 'd0, 1, 1, 0);
        this.d_osc_trim.configure(this, 4,  4, "RW", 0, 'd0, 1, 1, 0);
        this.d_ibias_trim.configure(this, 4,  0, "RW", 0, 'd0, 1, 1, 0);
    endfunction
    
endclass
`endif



