        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.d_afe_ac_cpl_e = uvm_reg_field::type_id::create("d_afe_ac_cpl_e");
        this.cvh_quad_shift = uvm_reg_field::type_id::create("cvh_quad_shift");
        this.cvh_quad_e = uvm_reg_field::type_id::create("cvh_quad_e");
        this.cvh_single_e = uvm_reg_field::type_id::create("cvh_single_e");
        this.d_cvh_dir_sel = uvm_reg_field::type_id::create("d_cvh_dir_sel");
        this.d_afe_ckchop_d = uvm_reg_field::type_id::create("d_afe_ckchop_d");
        this.afe_bw = uvm_reg_field::type_id::create("afe_bw");
        this.afe_gain = uvm_reg_field::type_id::create("afe_gain");
        this.cvh_cmode = uvm_reg_field::type_id::create("cvh_cmode");
        this.cvh_bias = uvm_reg_field::type_id::create("cvh_bias");
        this.d_afe_ac_cpl_e.configure(this, 1,  24, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_quad_shift.configure(this, 6,  18, "RW", 0, 'd5, 1, 1, 0);
        this.cvh_quad_e.configure(this, 1,  17, "RW", 0, 'd1, 1, 1, 0);
        this.cvh_single_e.configure(this, 1,  16, "RW", 0, 'd0, 1, 1, 0);
        this.d_cvh_dir_sel.configure(this, 6,  10, "RW", 0, 'd27, 1, 1, 0);
        this.d_afe_ckchop_d.configure(this, 1,  9, "RW", 0, 'd0, 1, 1, 0);
        this.afe_bw.configure(this, 1,  8, "RW", 0, 'd0, 1, 1, 0);
        this.afe_gain.configure(this, 2,  6, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_cmode.configure(this, 2,  4, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_bias.configure(this, 4,  0, "RW", 0, 'd10, 1, 1, 0);
    endfunction
    
endclass
`endif



/*----------------------------------------------------------------------
Class       : direct_regmap_shadow_shadow_6
-----------------------------------------------------------------------*/
`ifndef CLASS_direct_regmap_shadow_shadow_6
`define CLASS_direct_regmap_shadow_shadow_6

class direct_regmap_shadow_shadow_6 extends uvm_reg;
    `uvm_object_utils(direct_regmap_shadow_shadow_6)
    
    
    /*Overrides the output selection. For CAS 0 & 1, forces PWM output. For CAS 2 forces analog output
    */
    rand uvm_reg_field output_override;
    
    
    /*Selects the output type:
    0: Analog Ratiometric
    1: Analog No Ratiometric
    2: PWM
    3: PWM
    */
    rand uvm_reg_field cas_sel;
    
    
    /*Manchester shared output selection
    */
    rand uvm_reg_field manch_shared_out_sel;
    
    
    /*Manchested trigger disable.
    bit 1: OVLO DISABLE
    bit 0: PWM DISABLE
    */
    rand uvm_reg_field manch_trigger_dis;
    
    
    /*Temperature slope selection.
    
    */
    rand uvm_reg_field d_ratiometric_dis;
    
    
    /*Disables angle error correction.
    00: full correction
