        this.ups_watchdog_dis = uvm_reg_field::type_id::create("ups_watchdog_dis");
        this.mfs_h1_lim = uvm_reg_field::type_id::create("mfs_h1_lim");
        this.mfs_h2_lim = uvm_reg_field::type_id::create("mfs_h2_lim");
        this.die_id = uvm_reg_field::type_id::create("die_id");
        this.mov_ave_dis = uvm_reg_field::type_id::create("mov_ave_dis");
        this.temp_hyst_e = uvm_reg_field::type_id::create("temp_hyst_e");
        this.cvh_asm = uvm_reg_field::type_id::create("cvh_asm");
        this.d_afe_sdm_ckchop_e = uvm_reg_field::type_id::create("d_afe_sdm_ckchop_e");
        this.cvh_smode = uvm_reg_field::type_id::create("cvh_smode");
        this.output_override.configure(this, 1,  25, "RW", 0, 'd0, 1, 1, 0);
        this.cas_sel.configure(this, 2,  23, "RW", 0, 'd0, 1, 1, 0);
        this.manch_shared_out_sel.configure(this, 1,  22, "RW", 0, 'd0, 1, 1, 0);
        this.manch_trigger_dis.configure(this, 2,  20, "RW", 0, 'd0, 1, 1, 0);
        this.d_ratiometric_dis.configure(this, 1,  19, "RW", 0, 'd0, 1, 1, 0);
        this.angle_corr_dis.configure(this, 2,  17, "RW", 0, 'd0, 1, 1, 0);
        this.ups_bypass.configure(this, 1,  16, "RW", 0, 'd0, 1, 1, 0);
        this.ups_watchdog_dis.configure(this, 1,  15, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_h1_lim.configure(this, 4,  11, "RW", 0, 'd0, 1, 1, 0);
        this.mfs_h2_lim.configure(this, 4,  7, "RW", 0, 'd0, 1, 1, 0);
        this.die_id.configure(this, 1,  6, "RW", 0, 'd0, 1, 1, 0);
        this.mov_ave_dis.configure(this, 1,  5, "RW", 0, 'd0, 1, 1, 0);
        this.temp_hyst_e.configure(this, 1,  4, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_asm.configure(this, 1,  3, "RW", 0, 'd0, 1, 1, 0);
        this.d_afe_sdm_ckchop_e.configure(this, 1,  2, "RW", 0, 'd0, 1, 1, 0);
        this.cvh_smode.configure(this, 2,  0, "RW", 0, 'd2, 1, 1, 0);
    endfunction
    
