        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.cvh_st_dly = uvm_reg_field::type_id::create("cvh_st_dly");
        this.tt_hys = uvm_reg_field::type_id::create("tt_hys");
        this.h2a_slope = uvm_reg_field::type_id::create("h2a_slope");
        this.h1a_slope = uvm_reg_field::type_id::create("h1a_slope");
        this.cvh_st_dly.configure(this, 4,  21, "RW", 0, 'd0, 1, 1, 0);
        this.tt_hys.configure(this, 8,  13, "RW", 0, 'd0, 1, 1, 0);
        this.h2a_slope.configure(this, 6,  7, "RW", 0, 'd0, 1, 1, 0);
        this.h1a_slope.configure(this, 7,  0, "RW", 0, 'd0, 1, 1, 0);
    endfunction
    
endclass
`endif



