/*----------------------------------------------------------------------
Class       : direct_regmap_volatile_ee_status
-----------------------------------------------------------------------*/
`ifndef CLASS_direct_regmap_volatile_ee_status
`define CLASS_direct_regmap_volatile_ee_status

class direct_regmap_volatile_ee_status extends uvm_reg;
    `uvm_object_utils(direct_regmap_volatile_ee_status)
    
    
    /*Latched and held high when a DBE has occurred.
    */
    rand uvm_reg_field ee_dbe_flag;
    
    
    /*Latched and held high when a SBE has occurred.
    */
    rand uvm_reg_field ee_sbe_flag;
    
    
    /*Reflects bits [29:24] to be written to the EEPROM or read from the EEPROM. This allows for a manual write to the EEPROM or will contain data read from the EEPROM if margining or self check fails.
    */
    rand uvm_reg_field ee_ecc;
    
    
    /*Reflects the read/write address to the EEPROM. This allows for a manual write to the EEPROM or will contain data read from the EEPROM if margining or self check fails.
    The default value must point to the POR trimming data.
    */
    rand uvm_reg_field ee_addr;
    
    
    /*Status of the most recent EEPROM write error.
    Bit[4]
    0: error occurred during erase
    1: error occurred during program
    Bit[3]
    0: error occurred during Ramp Up
    1: error occurred during Ramp Down
    Bit 2: Program Pulse value
    Bit 1: hlat value
    Bit 0: llat value
    */
    rand uvm_reg_field ee_err_status;
    
    
    /*High to indicate an error occurred during charge pump ramp. ee_err_status stores information about the error. This bit is latch and hold with clear on read.
    */
    rand uvm_reg_field cp_err;
    
    
    /*Indicates an EEPROM write error occurred. This bit is latch and hold with clear on read.
    */
    rand uvm_reg_field ee_err;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
        field_19: coverpoint {m_current[19],m_data[19]} iff (!m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_18: coverpoint {m_current[18],m_data[18]} iff (!m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_12: coverpoint {m_current[12],m_data[12]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_13: coverpoint {m_current[13],m_data[13]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_14: coverpoint {m_current[14],m_data[14]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_15: coverpoint {m_current[15],m_data[15]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_16: coverpoint {m_current[16],m_data[16]} iff (!m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_17: coverpoint {m_current[17],m_data[17]} iff (!m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_7: coverpoint {m_current[7],m_data[7]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_8: coverpoint {m_current[8],m_data[8]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_9: coverpoint {m_current[9],m_data[9]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_10: coverpoint {m_current[10],m_data[10]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_11: coverpoint {m_current[11],m_data[11]} iff (!m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
    endgroup
    
    covergroup rd_cg_bits;
        
        field_19: coverpoint {m_current[19],m_data[19]} iff (m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_18: coverpoint {m_current[18],m_data[18]} iff (m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_12: coverpoint {m_current[12],m_data[12]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_13: coverpoint {m_current[13],m_data[13]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_14: coverpoint {m_current[14],m_data[14]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_15: coverpoint {m_current[15],m_data[15]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_16: coverpoint {m_current[16],m_data[16]} iff (m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_17: coverpoint {m_current[17],m_data[17]} iff (m_is_read && m_be[2])
        {
            illegal_bins b_x = {1,2};
        }
        field_7: coverpoint {m_current[7],m_data[7]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_8: coverpoint {m_current[8],m_data[8]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_9: coverpoint {m_current[9],m_data[9]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_10: coverpoint {m_current[10],m_data[10]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_11: coverpoint {m_current[11],m_data[11]} iff (m_is_read && m_be[1])
        {
            illegal_bins b_x = {1,2};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_3: coverpoint {m_current[3],m_data[3]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_4: coverpoint {m_current[4],m_data[4]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_5: coverpoint {m_current[5],m_data[5]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_6: coverpoint {m_current[6],m_data[6]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        
    endgroup
    
    covergroup wr_cg_vals;
        
        ee_dbe_flag : coverpoint ee_dbe_flag.value[0:0];
        
        ee_sbe_flag : coverpoint ee_sbe_flag.value[0:0];
        
        ee_ecc : coverpoint ee_ecc.value[5:0];
        
        ee_addr : coverpoint ee_addr.value[4:0];
        
    endgroup
    
    covergroup rd_cg_vals;
        
        ee_dbe_flag : coverpoint ee_dbe_flag.value[0:0];
        
        ee_sbe_flag : coverpoint ee_sbe_flag.value[0:0];
        
        ee_ecc : coverpoint ee_ecc.value[5:0];
        
        ee_addr : coverpoint ee_addr.value[4:0];
        
        ee_err_status : coverpoint ee_err_status.value[4:0];
        
        cp_err : coverpoint cp_err.value[0:0];
        
        ee_err : coverpoint ee_err.value[0:0];
        
    endgroup
    
    // Function : new
    
    function new(string name = "direct_regmap_volatile_ee_status");
        super.new(name, 32, build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));
        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.ee_dbe_flag = uvm_reg_field::type_id::create("ee_dbe_flag");
        this.ee_sbe_flag = uvm_reg_field::type_id::create("ee_sbe_flag");
        this.ee_ecc = uvm_reg_field::type_id::create("ee_ecc");
        this.ee_addr = uvm_reg_field::type_id::create("ee_addr");
        this.ee_err_status = uvm_reg_field::type_id::create("ee_err_status");
        this.cp_err = uvm_reg_field::type_id::create("cp_err");
        this.ee_err = uvm_reg_field::type_id::create("ee_err");
        this.ee_dbe_flag.configure(this, 1,  19, "RW", 0, 'd0, 1, 1, 0);
        this.ee_sbe_flag.configure(this, 1,  18, "RW", 0, 'd0, 1, 1, 0);
        this.ee_ecc.configure(this, 6,  12, "RW", 0, 'd0, 1, 1, 0);
        this.ee_addr.configure(this, 5,  7, "RW", 0, 'd4, 1, 1, 0);
        this.ee_err_status.configure(this, 5,  2, "RO", 0, 'd0, 1, 1, 0);
        this.cp_err.configure(this, 1,  1, "RC", 0, 'd0, 1, 1, 0);
        this.ee_err.configure(this, 1,  0, "RC", 0, 'd0, 1, 1, 0);
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_HW_RESET_TEST", 1, this);
        
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_BIT_BASH_TEST", 1, this);
        
        uvm_resource_db#(bit)::set({"REG::", this.get_full_name()}, "NO_REG_ACCESS_TEST",1,this);
        
    endfunction
    
endclass
`endif



