/*----------------------------------------------------------------------
Class       : direct_regmap_volatile_ee_patt_tst
-----------------------------------------------------------------------*/
`ifndef CLASS_direct_regmap_volatile_ee_patt_tst
`define CLASS_direct_regmap_volatile_ee_patt_tst

class direct_regmap_volatile_ee_patt_tst extends uvm_reg;
    `uvm_object_utils(direct_regmap_volatile_ee_patt_tst)
    
    
    /*Defines the pattern that will be checked when reading the EEPROM.
    00: All 0s
    01: All 1s
    10: Checker board starting at 0x0 with '010101.'
    11: Checker board starting at 0x0 with '101010.'
    */
    rand uvm_reg_field pat_test_pattern;
    
    
    /*  00: Reset condition (no result from pat testing)
    01: Pass, no failure detected during pat testing
    10: Fail, failure detected during pat testing
    11: Running, pat test is still running
    */
    rand uvm_reg_field pat_test_status;
    
    
    /*Write to 1 to start pattern check testing. If EE_LOOP is low, this bit will self clear when address 0xB is reached. If EE_LOOP is high, this bit must be written to 0 to stop test. This bit always clears on a fail.
    */
    rand uvm_reg_field pat_test_start;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
        field_3: coverpoint {m_current[3],m_data[3]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_4: coverpoint {m_current[4],m_data[4]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
    endgroup
    
    covergroup rd_cg_bits;
        
        field_3: coverpoint {m_current[3],m_data[3]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_4: coverpoint {m_current[4],m_data[4]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2,3};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        
    endgroup
    
    covergroup wr_cg_vals;
        
        pat_test_pattern : coverpoint pat_test_pattern.value[1:0];
        
        pat_test_start : coverpoint pat_test_start.value[0:0];
        
    endgroup
    
    covergroup rd_cg_vals;
        
        pat_test_pattern : coverpoint pat_test_pattern.value[1:0];
        
        pat_test_status : coverpoint pat_test_status.value[1:0];
        
        pat_test_start : coverpoint pat_test_start.value[0:0];
        
    endgroup
    
    // Function : new
    
    function new(string name = "direct_regmap_volatile_ee_patt_tst");
        super.new(name, 32, build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));
        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.pat_test_pattern = uvm_reg_field::type_id::create("pat_test_pattern");
        this.pat_test_status = uvm_reg_field::type_id::create("pat_test_status");
        this.pat_test_start = uvm_reg_field::type_id::create("pat_test_start");
        this.pat_test_pattern.configure(this, 2,  3, "RW", 0, 'd0, 1, 1, 0);
        this.pat_test_status.configure(this, 2,  1, "RO", 0, 'd0, 1, 1, 0);
        this.pat_test_start.configure(this, 1,  0, "RW", 0, 'd0, 1, 1, 0);
    endfunction
    
endclass
`endif



