class direct_regmap_volatile_dft extends uvm_reg;
    `uvm_object_utils(direct_regmap_volatile_dft)
    
    
    /*When '1' is written, the digital signal path is reset.
    When is read, always returns '0'.
    */
    rand uvm_reg_field soft_rst;
    
    
    /*ABIST pass.
    
    */
    rand uvm_reg_field abist_pass1_fail0;
    
    
    /*LBIST pass.
    
    */
    rand uvm_reg_field lbist_pass1_fail0;
    
    
    /*BIST done. When '1', LBIST and ABIST has finished.
    
    */
    rand uvm_reg_field bist_done;
    
    
    /*BIST start. When '1', LBIST and then ABIST start (depending on lbist_e and abist_e EEPROM/Shadow fields).
    
    */
    rand uvm_reg_field bist_start;
    
    
    /*Delay fault enable.
    
    */
    rand uvm_reg_field dly_fault_e;
    
    
    /*Iddq mode enable.
    
    */
    rand uvm_reg_field iddq_mode_e;
    
    
    /*Scan mode enable.
    When is read, always returns '0'.
    
    */
    rand uvm_reg_field scan_mode_e;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
        field_31: coverpoint {m_current[31],m_data[31]} iff (!m_is_read && m_be[3])
        {
            illegal_bins b_x = {1,2};
