/*----------------------------------------------------------------------
Class       : direct_regmap_volatile_volatile_52
-----------------------------------------------------------------------*/
`ifndef CLASS_direct_regmap_volatile_volatile_52
`define CLASS_direct_regmap_volatile_volatile_52

class direct_regmap_volatile_volatile_52 extends uvm_reg;
    `uvm_object_utils(direct_regmap_volatile_volatile_52)
    
    
    /*Selects the angle input to the v_angle_val_f.
    0000: v_angle_val_f = dfe_angle_val (digital front end)
    0001: v_angle_val_f = ma_angle_val (moving average)
    0010: v_angle_val_f = erc_angle_val (error correction)
    0011: v_angle_val_f = lin_angle_val (linearization)
    0100: v_angle_val_f = ac_angle_val (average calculator)
    0101: v_angle_val_f = aa_angle_val (angle adjust)
    0110: v_angle_val_f = hys_angle_val (hysteresis)
    0111: v_angle_val_f = ss_angle_val (short stroke)
    1000: v_angle_val_f = mp_angle_val (mapper)
    1001: v_angle_val_f = int_angle_val (interpolator)
    */
    rand uvm_reg_field angle_sel;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
        field_0: coverpoint {m_current[0],m_data[0]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_3: coverpoint {m_current[3],m_data[3]} iff (!m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
    endgroup
    
    covergroup rd_cg_bits;
        
        field_0: coverpoint {m_current[0],m_data[0]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_1: coverpoint {m_current[1],m_data[1]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_2: coverpoint {m_current[2],m_data[2]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        field_3: coverpoint {m_current[3],m_data[3]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        
    endgroup
    
    covergroup wr_cg_vals;
        
        angle_sel : coverpoint angle_sel.value[3:0];
        
    endgroup
    
    covergroup rd_cg_vals;
        
        angle_sel : coverpoint angle_sel.value[3:0];
        
    endgroup
    
    // Function : new
    
    function new(string name = "direct_regmap_volatile_volatile_52");
        super.new(name, 32, build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));
        add_coverage(build_coverage(UVM_CVR_REG_BITS + UVM_CVR_FIELD_VALS));            //Added because build coverage in the line above doesn’t work due to a bug in UVM 1.1 library
        
        if (has_coverage(UVM_CVR_REG_BITS)) begin
            wr_cg_bits = new();
            rd_cg_bits = new();
        end
        
        if (has_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals = new();
            rd_cg_vals = new();
        end
        
    endfunction
    
    protected virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en, bit is_read, uvm_reg_map map);
        super.sample(data, byte_en, is_read, map);
        if (get_coverage(UVM_CVR_REG_BITS)) begin
            m_current = get();
            m_data    = data;
            m_be      = byte_en;
            m_is_read = is_read;
            
            if(!is_read) begin
                wr_cg_bits.sample();
            end
            
            if(is_read) begin
                rd_cg_bits.sample();
            end
            
        end
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            if(!is_read) begin
                wr_cg_vals.sample();
            end
            if(is_read) begin
                rd_cg_vals.sample();
            end
            
        end
    endfunction
    
    virtual function void sample_values();
        super.sample_values();
        if (get_coverage(UVM_CVR_FIELD_VALS)) begin
            wr_cg_vals.sample();
            rd_cg_vals.sample();
        end
    endfunction
    
    // Function : build
    
    virtual function void build();
        this.angle_sel = uvm_reg_field::type_id::create("angle_sel");
        this.angle_sel.configure(this, 4,  0, "RW", 0, 'd0, 1, 1, 0);
    endfunction
    
endclass
`endif



