    */
    rand uvm_reg_field st_flg_ovlo;
    
    
    /*Under voltage error.
    */
    rand uvm_reg_field st_flg_uvlo;
    
    
    /*EEPROM double bit error has ever ocurred.
    */
    rand uvm_reg_field st_flg_eedbe;
    
    
    /*Missing magnet error.
    */
    rand uvm_reg_field st_flg_mmag;
    
    
    local uvm_reg_data_t m_current;
    local uvm_reg_data_t m_data;
    local uvm_reg_data_t m_be;
    local bit            m_is_read;
    
    covergroup wr_cg_bits;
        
