        {
            illegal_bins b_x = {1,2};
        }
        field_0: coverpoint {m_current[0],m_data[0]} iff (m_is_read && m_be[0])
        {
            illegal_bins b_x = {1,2};
        }
        
    endgroup
    
    
    
    covergroup rd_cg_vals;
        
        st_flg_inter : coverpoint st_flg_inter.value[0:0];
        
        st_flg_eerld : coverpoint st_flg_eerld.value[0:0];
        
        st_flg_maxang : coverpoint st_flg_maxang.value[0:0];
        
        st_flg_minang : coverpoint st_flg_minang.value[0:0];
        
        st_flg_ovlo : coverpoint st_flg_ovlo.value[0:0];
        
        st_flg_uvlo : coverpoint st_flg_uvlo.value[0:0];
        
