/*----------------------------------------------------------------------
Class       : direct_regmap_block

Description :





Note 0: Do not change Names, Addresses, or Bit positions for fields colored in purple.
Note 1: Fields colored in orange are optional and can be removed.
Note 2: "dev_lock" bit is a special bit to lock access. Do not change its name.
Note 3: The default value of the "ee_addr" field must be the address where the trim fields (like "d_osc_trim" and/or "d_ibias_trim") are in.
Note 4: Avoid shadowing ECC and unused bits in EEPROM in sake of area savings.
Note 5: If all EEPROM/SHADOW memory matches names and bit positions (ECC and unused bits must be omitted in shadow). Reserved registers in EEPROM are shadowed. Unused registers in EEPROM do not have a shadow register associated.
-----------------------------------------------------------------------*/
`ifndef CLASS_direct_regmap_block
`define CLASS_direct_regmap_block

class direct_regmap_block extends uvm_reg_block;
    `uvm_object_utils(direct_regmap_block)
    
    
    rand direct_regmap_eeprom eeprom;
    
    
    rand direct_regmap_shadow shadow;
    
    
    rand direct_regmap_volatile volatile;
    
    
    
    
    local uvm_reg_addr_t m_offset;
    covergroup cg_addr;
        
        eeprom : coverpoint m_offset
        {
            bins hit =  { ['h0 : 'h7F] };
        }
        shadow : coverpoint m_offset
        {
            bins hit =  { ['h20 : 'h9B] };
        }
        volatile : coverpoint m_offset
        {
            bins hit =  { ['h40 : 'h103] };
        }
        
    endgroup
    
    // Function : new
    
    function new(string name = "direct_regmap_block");
        super.new(name, build_coverage(UVM_CVR_ADDR_MAP));
        
        if (has_coverage(UVM_CVR_ADDR_MAP)) begin
            cg_addr = new();
        end
        
    endfunction
    
    
    // Function : build
    
    virtual function void build();
        //create
        
        eeprom   =   direct_regmap_eeprom::type_id::create("eeprom");
        shadow   =   direct_regmap_shadow::type_id::create("shadow");
        volatile   =   direct_regmap_volatile::type_id::create("volatile");
        
        
        //config
        eeprom.configure(this, null, "eeprom");
        shadow.configure(this, null, "shadow");
        volatile.configure(this, null, "volatile");
        
        //build
        eeprom.build();
        shadow.build();
        volatile.build();
        
        //define default map and add reg/regfiles
        
        
        default_map= create_map("default_map", 'h0, 4, UVM_BIG_ENDIAN, 0);
        
        eeprom.map( default_map, 'h0);
        shadow.map( default_map, 'h20);
        volatile.map( default_map, 'h40);
        
        
        eeprom.clear_hdl_path();
        eeprom.add_hdl_path("");
        eeprom.eeprom_0.clear_hdl_path();
        eeprom.eeprom_0.add_hdl_path_slice("u_eeprom.eeprom_array.mem[0]",0,32);
        eeprom.eeprom_1.clear_hdl_path();
        eeprom.eeprom_1.add_hdl_path_slice("u_eeprom.eeprom_array.mem[1]",0,32);
